// QueryServer is the server API for Query service.
type QueryServer interface {
	// Parameters queries the parameters of the module.
	Params(context.Context, *QueryParamsRequest) (*QueryParamsResponse, error)
	// Class returns one class.
	Class(context.Context, *QueryClassRequest) (*QueryClassResponse, error)
	// Classes lists all classes.
	Classes(context.Context, *QueryClassesRequest) (*QueryClassesResponse, error)
	// ClassesByOwner lists the classes an address owns.
	ClassesByOwner(context.Context, *QueryClassesByOwnerRequest) (*QueryClassesByOwnerResponse, error)
	// Token returns one token.
	Token(context.Context, *QueryTokenRequest) (*QueryTokenResponse, error)
	// Tokens lists the tokens of a class.
	Tokens(context.Context, *QueryTokensRequest) (*QueryTokensResponse, error)
	// TokensByOwner lists the tokens an address owns.
	TokensByOwner(context.Context, *QueryTokensByOwnerRequest) (*QueryTokensByOwnerResponse, error)
	// Owner returns a token's owner.
	Owner(context.Context, *QueryOwnerRequest) (*QueryOwnerResponse, error)
	// Supply returns a class's supply counters.
	Supply(context.Context, *QuerySupplyRequest) (*QuerySupplyResponse, error)
	// Listing returns a token's active listing.
	Listing(context.Context, *QueryListingRequest) (*QueryListingResponse, error)
	// Listings lists active listings, optionally for one class.
	Listings(context.Context, *QueryListingsRequest) (*QueryListingsResponse, error)
	// ListingsBySeller lists a seller's active listings.
	ListingsBySeller(context.Context, *QueryListingsBySellerRequest) (*QueryListingsBySellerResponse, error)
	// Inbox lists an address's open incoming items.
	Inbox(context.Context, *QueryInboxRequest) (*QueryInboxResponse, error)
	// Outbox lists an address's open outgoing items.
	Outbox(context.Context, *QueryOutboxRequest) (*QueryOutboxResponse, error)
	// ReceivePolicy returns an address's effective receive policy.
	ReceivePolicy(context.Context, *QueryReceivePolicyRequest) (*QueryReceivePolicyResponse, error)
	// PendingClassOwner returns a class's open handover proposal.
	PendingClassOwner(context.Context, *QueryPendingClassOwnerRequest) (*QueryPendingClassOwnerResponse, error)
	// HideRecord returns one hide record.
	HideRecord(context.Context, *QueryHideRecordRequest) (*QueryHideRecordResponse, error)
	// HideRecordsByTarget lists every hide record for a class (token_id 0) or token.
	HideRecordsByTarget(context.Context, *QueryHideRecordsByTargetRequest) (*QueryHideRecordsByTargetResponse, error)
	// PublicMintQuote prices a public mint.
	// MediaProposals lists the open media proposals of a token.
	MediaProposals(context.Context, *QueryMediaProposalsRequest) (*QueryMediaProposalsResponse, error)
	PublicMintQuote(context.Context, *QueryPublicMintQuoteRequest) (*QueryPublicMintQuoteResponse, error)
}

